import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Troubleshoot port forwarding","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/upnpumpkin/docs/troubleshooting.md"},"headers":[],"relativePath":"packages/upnpumpkin/docs/troubleshooting.md","filePath":"packages/upnpumpkin/docs/troubleshooting.md","lastUpdated":1792252144000}`),a={name:`packages/upnpumpkin/docs/troubleshooting.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="troubleshoot-port-forwarding" tabindex="-1">Troubleshoot port forwarding <a class="header-anchor" href="#troubleshoot-port-forwarding" aria-label="Permalink to “Troubleshoot port forwarding”">​</a></h1><p>Start with <code>/upnp status</code>. It shows whether UPnPumpkin has found a router and whether each requested port is open, still being opened, or failed. The command&#39;s state helps narrow down which part of the network to check.</p><h2 id="no-router-is-found" tabindex="-1">No router is found <a class="header-anchor" href="#no-router-is-found" aria-label="Permalink to “No router is found”">​</a></h2><p>Make sure UPnP or NAT-PMP is enabled in the router settings and the server host is on the router&#39;s local network. UPnP normally uses multicast discovery. If the server&#39;s network blocks multicast, set <code>router.upnp_search</code> in <code>plugins/data/UPnPumpkin/config.toml</code> to the router&#39;s IPv4 address and UPnP port, for example <code>192.168.1.1:1900</code>. Run <code>/upnp reload</code> to apply the change.</p><p>For NAT-PMP, set <code>router.nat_pmp_gateway</code> to the gateway&#39;s IPv4 address and port (usually <code>192.168.1.1:5351</code>) if automatic probing does not find it. In a container or a network with multiple routers, check that the server can reach the router and receive its replies; a container network may not pass the discovery traffic the router needs.</p><h2 id="a-port-is-not-opened-or-players-cannot-connect" tabindex="-1">A port is not opened or players cannot connect <a class="header-anchor" href="#a-port-is-not-opened-or-players-cannot-connect" aria-label="Permalink to “A port is not opened or players cannot connect”">​</a></h2><p>In <code>/upnp status</code>, look at the state and reason shown for the Java and Bedrock ports. Confirm <code>java.port</code> and <code>bedrock.port</code> match the server listeners. Java uses TCP and Bedrock uses UDP. The router mapping does not change host firewall rules, so allow the same ports and protocols through the server&#39;s firewall.</p><p>The router also needs a public internet-side address to accept inbound connections. If its address is private or shared through carrier-grade NAT, a mapping cannot make the server reachable from the internet. A server machine that already has a public address does not need a router mapping.</p><p>If <code>/upnp status</code> reports that the router is unsupported, UPnPumpkin intentionally opens nothing for that router. Forward the ports manually in the router settings instead.</p><h2 id="a-plugin-s-requested-port-closes-or-is-rejected" tabindex="-1">A plugin&#39;s requested port closes or is rejected <a class="header-anchor" href="#a-plugin-s-requested-port-closes-or-is-rejected" aria-label="Permalink to “A plugin&#39;s requested port closes or is rejected”">​</a></h2><p>Check that <code>plugins.allow_requests</code> is enabled and the requesting plugin is still refreshing its request. UPnPumpkin drops a request after five minutes without a refresh, and the requester should stop its watcher when it no longer needs the port. Each plugin can hold up to <code>plugins.max_requests_per_plugin</code> mappings at once; a request beyond that limit is rejected.</p><p>After changing settings in <code>plugins/data/UPnPumpkin/config.toml</code>, run <code>/upnp reload</code>. Changes also take effect after a server restart.</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};